// Same 200,000 bytes written two ways: one syscall per byte vs. one big syscall.
const fs = require('fs');
const os = require('os');
const path = require('path');

const N = 200_000;
const file = path.join(os.tmpdir(), 'syscall-cost.bin');

function timeIt(label, fn) {
  const t0 = process.hrtime.bigint();      // vDSO clock read: no kernel entry on Linux
  fn();
  const ms = Number(process.hrtime.bigint() - t0) / 1e6;
  console.log(`${label.padEnd(26)} ${ms.toFixed(1).padStart(7)} ms`);
  return ms;
}

const fd = fs.openSync(file, 'w');
const oneByte = Buffer.from('x');
const slow = timeIt(`${N} x write(1 byte)`, () => {
  for (let i = 0; i < N; i++) fs.writeSync(fd, oneByte);   // N kernel crossings
});
fs.closeSync(fd);

const fd2 = fs.openSync(file, 'w');
const big = Buffer.alloc(N, 'x');
const fast = timeIt(`1 x write(${N} bytes)`, () => {
  fs.writeSync(fd2, big);                                   // 1 kernel crossing
});
fs.closeSync(fd2);
fs.unlinkSync(file);

console.log(`per-syscall cost ≈ ${((slow * 1e6) / N).toFixed(0)} ns (incl. JS->C++ binding overhead)`);
console.log(`batched is ~${Math.round(slow / fast)}x faster`);

