// libuv runs crypto.pbkdf2 (and fs.*, dns.lookup, zlib) on a thread pool, 4 threads by default.
// Run:  node threadpool.js          then   UV_THREADPOOL_SIZE=8 node threadpool.js
const crypto = require('crypto');
const start = Date.now();
const JOBS = 8;

for (let i = 1; i <= JOBS; i++) {
  crypto.pbkdf2('secret', 'salt', 300_000, 64, 'sha512', () => {
    console.log(`job ${i} done at ${Date.now() - start} ms`);
  });
}
// Meanwhile, the event loop thread itself is free:
setTimeout(() => console.log(`timer fired at ${Date.now() - start} ms (loop not blocked)`), 10);
